const seen = {};
const out = [];
const check = (v, min, max, label, issues) => {
  if (typeof v !== 'number' || isNaN(v) || v < min || v > max) {
    issues.push(label + ' missing or invalid');
    return null;
  }
  return v;
};
$input.all().forEach((item) => {
  const p = item.json;
  const id = String(p.id || '').trim();
  if (!id || seen[id]) {
    return;
  }
  seen[id] = true;
  const issues = [];
  let name = String(p.name || '').trim();
  if (!name) {
    name = 'Unknown';
    issues.push('Name missing');
  }
  let complaint = String(p.complaint || '').trim();
  if (!complaint) {
    complaint = 'not provided';
    issues.push('Complaint missing');
  }
  const age = check(p.age, 0, 120, 'Age', issues);
  const temp = check(p.temp, 30, 45, 'Temperature', issues);
  const pulse = check(p.pulse, 20, 250, 'Pulse', issues);
  const systolic = check(p.systolic, 50, 260, 'Blood pressure', issues);
  const spo2 = check(p.spo2, 50, 100, 'Oxygen level', issues);
  out.push({ json: { id: id, name: name, age: age, gender: p.gender || 'NA', complaint: complaint, temp: temp, pulse: pulse, systolic: systolic, spo2: spo2, insured: p.insured === true, dataIssues: issues } });
});
return out;

const has = (text, words) => words.some((w) => text.indexOf(w) !== -1);
return $input.all().map((item) => {
  const p = item.json;
  const text = String(p.complaint).toLowerCase();
  let score = 0;
  const reasons = [];
  if (p.spo2 !== null && p.spo2 < 90) {
    score += 4;
    reasons.push('Low oxygen');
  } else if (p.spo2 !== null && p.spo2 < 94) {
    score += 2;
    reasons.push('Slightly low oxygen');
  }
  if (p.temp !== null && p.temp >= 39.5) {
    score += 2;
    reasons.push('Very high temperature');
  } else if (p.temp !== null && p.temp >= 38) {
    score += 1;
    reasons.push('Fever');
  }
  if (p.pulse !== null && (p.pulse > 120 || p.pulse < 50)) {
    score += 2;
    reasons.push('Abnormal pulse');
  } else if (p.pulse !== null && p.pulse > 100) {
    score += 1;
    reasons.push('Fast pulse');
  }
  if (p.systolic !== null && (p.systolic >= 180 || p.systolic < 90)) {
    score += 3;
    reasons.push('Abnormal blood pressure');
  } else if (p.systolic !== null && p.systolic >= 140) {
    score += 1;
    reasons.push('High blood pressure');
  }
  if (has(text, ['chest pain', 'breathing', 'bleeding', 'unconscious', 'stroke'])) {
    score += 4;
    reasons.push('Red-flag complaint');
  } else if (has(text, ['vomit'])) {
    score += 1;
    reasons.push('Vomiting');
  }
  if (p.age !== null && (p.age >= 65 || p.age <= 5)) {
    score += 1;
    reasons.push('Age risk group');
  }
  let level = 4;
  let label = 'Routine';
  if (score >= 6) {
    level = 1;
    label = 'Critical';
  } else if (score >= 4) {
    level = 2;
    label = 'Urgent';
  } else if (score >= 2) {
    level = 3;
    label = 'Semi-urgent';
  }
  return { json: Object.assign({}, p, { triageScore: score, triageLevel: level, triageLabel: label, triageReasons: reasons }) };
});

const has = (text, words) => words.some((w) => text.indexOf(w) !== -1);
return $input.all().map((item) => {
  const p = item.json;
  const text = String(p.complaint).toLowerCase();
  let department = 'General Medicine';
  if (p.triageLevel === 1) {
    department = 'Emergency';
  } else if (has(text, ['chest', 'heart', 'palpitation'])) {
    department = 'Cardiology';
  } else if (p.age !== null && p.age < 14) {
    department = 'Pediatrics';
  } else if (has(text, ['knee', 'fracture', 'bone', 'joint', 'fall'])) {
    department = 'Orthopedics';
  } else if (has(text, ['skin', 'rash', 'itch'])) {
    department = 'Dermatology';
  } else if (has(text, ['headache', 'dizz', 'seizure'])) {
    department = 'Neurology';
  } else if (has(text, ['stomach', 'vomit', 'abdom'])) {
    department = 'Gastroenterology';
  }
  return { json: Object.assign({}, p, { department: department }) };
});

const roster = {
  'Emergency': { doctors: ['Dr. Mehta', 'Dr. Iyer'], rooms: ['ER-1', 'ER-2', 'ER-3'] },
  'Cardiology': { doctors: ['Dr. Rao', 'Dr. Sen'], rooms: ['C-101', 'C-102'] },
  'Pediatrics': { doctors: ['Dr. Gupta'], rooms: ['P-201', 'P-202'] },
  'Orthopedics': { doctors: ['Dr. Khanna'], rooms: ['O-301'] },
  'Dermatology': { doctors: ['Dr. Joshi'], rooms: ['D-401'] },
  'Neurology': { doctors: ['Dr. Menon'], rooms: ['N-501'] },
  'Gastroenterology': { doctors: ['Dr. Das'], rooms: ['G-601'] },
  'General Medicine': { doctors: ['Dr. Nair', 'Dr. Bose'], rooms: ['GM-1', 'GM-2', 'GM-3'] }
};
const counts = {};
return $input.all().map((item) => {
  const p = item.json;
  const r = roster[p.department] || roster['General Medicine'];
  const n = counts[p.department] || 0;
  counts[p.department] = n + 1;
  return { json: Object.assign({}, p, { doctor: r.doctors[n % r.doctors.length], room: r.rooms[n % r.rooms.length] }) };
});

const fees = {
  'Emergency': 3000,
  'Cardiology': 1500,
  'Pediatrics': 800,
  'Orthopedics': 1200,
  'Dermatology': 700,
  'Neurology': 1400,
  'Gastroenterology': 1000,
  'General Medicine': 500
};
return $input.all().map((item) => {
  const p = item.json;
  const fee = fees[p.department] || 500;
  let surcharge = 0;
  if (p.triageLevel === 1) {
    surcharge = 2000;
  } else if (p.triageLevel === 2) {
    surcharge = 500;
  }
  const totalBill = fee + surcharge;
  const insuranceCovered = p.insured ? Math.round(totalBill * 0.7) : 0;
  const patientPays = totalBill - insuranceCovered;
  return { json: Object.assign({}, p, { consultationFee: fee, surcharge: surcharge, totalBill: totalBill, insuranceCovered: insuranceCovered, patientPays: patientPays }) };
});

const labs = {
  'Emergency': ['ECG', 'Blood panel', 'Oxygen monitoring'],
  'Cardiology': ['ECG', 'Lipid profile'],
  'Pediatrics': ['Throat swab', 'CBC'],
  'Orthopedics': ['X-ray'],
  'Dermatology': ['Skin examination'],
  'Neurology': ['Blood pressure check', 'CT scan if the doctor advises'],
  'Gastroenterology': ['Stool test', 'Ultrasound if the doctor advises'],
  'General Medicine': ['CBC', 'Chest X-ray if the doctor advises']
};
return $input.all().map((item) => {
  const p = item.json;
  return { json: Object.assign({}, p, { labOrders: labs[p.department] || ['CBC'] }) };
});

const items = $input.all();
items.sort((a, b) => (a.json.triageLevel - b.json.triageLevel) || (b.json.triageScore - a.json.triageScore) || (a.json.id < b.json.id ? -1 : 1));
return items;

return $input.all().map((item) => {
  const p = item.json;
  return { json: { id: p.id, name: p.name, alert: '🚨 CODE RED: ' + p.name + ' (' + p.id + ') - ' + p.complaint, action: 'Move immediately to ' + p.room + ' with ' + p.doctor, reasons: p.triageReasons.join(', ') } };
});

const pad = (n) => (n < 10 ? '0' + n : String(n));
const slots = {};
return $input.all().map((item) => {
  const p = item.json;
  const n = slots[p.doctor] || 0;
  slots[p.doctor] = n + 1;
  const mins = 9 * 60 + n * 15;
  const time = pad(Math.floor(mins / 60)) + ':' + pad(mins % 60);
  return { json: { id: p.id, name: p.name, doctor: p.doctor, room: p.room, appointment: time, message: 'Appointment for ' + p.name + ' with ' + p.doctor + ' at ' + time + ' in room ' + p.room } };
});

const items = $input.all().map((x) => x.json);
const count = (key) => {
  const r = {};
  items.forEach((i) => {
    r[i[key]] = (r[i[key]] || 0) + 1;
  });
  return r;
};
const fmt = (obj) => Object.keys(obj).map((k) => k + ': ' + obj[k]).join(', ');
const sum = (key) => items.reduce((t, i) => t + i[key], 0);
const byTriage = count('triageLabel');
const byDepartment = count('department');
const byDoctor = count('doctor');
const totalBilled = sum('totalBill');
const insuranceCovered = sum('insuranceCovered');
const patientPays = sum('patientPays');
const withIssues = items.filter((i) => i.dataIssues.length > 0).length;
const critical = items.filter((i) => i.triageLevel === 1).map((i) => '- ' + i.id + ' ' + i.name + ' -> ' + i.room + ' (' + i.doctor + ')');
const summary = [
  '🏥 Hospital Daily Summary',
  'Patients today: ' + items.length,
  'By triage: ' + fmt(byTriage),
  'By department: ' + fmt(byDepartment),
  'Doctor load: ' + fmt(byDoctor),
  'Total billed: Rs ' + totalBilled,
  'Insurance covers: Rs ' + insuranceCovered,
  'Patients pay: Rs ' + patientPays,
  'Records with data issues: ' + withIssues,
  '',
  '🚨 Critical patients:',
  critical.length ? critical.join('\n') : '- none'
].join('\n');
return [{ json: { patients: items.length, byTriage: byTriage, byDepartment: byDepartment, byDoctor: byDoctor, totalBilled: totalBilled, insuranceCovered: insuranceCovered, patientPays: patientPays, withIssues: withIssues, summary: summary } }];

const d = $input.first().json;
const items = $('Sort by Triage').all().map((x) => x.json);
const rows = items.map((i) => '| ' + i.id + ' | ' + i.name + ' | ' + (i.age === null ? '-' : i.age) + ' | ' + i.triageLabel + ' | ' + i.department + ' | ' + i.doctor + ' | ' + i.room + ' | Rs ' + i.totalBill + ' |');
const notes = items.filter((i) => i.dataIssues.length > 0).map((i) => '- ' + i.id + ' ' + i.name + ': ' + i.dataIssues.join('; '));
const report = [
  '# Hospital Patient Flow Report (demo data)',
  '',
  d.summary,
  '',
  '## Patients (most urgent first)',
  '| ID | Name | Age | Triage | Department | Doctor | Room | Bill |',
  '|---|---|---|---|---|---|---|---|'
].concat(rows).concat(['', '## Data issues to fix', notes.length ? notes.join('\n') : '- none', '', 'Note: this is a demo with sample data. It is not medical advice.']).join('\n');
return [{ json: { patients: d.patients, report: report } }];
